func (this *Grvt) ParseOrder(order any, optionalArgs ...any) any {
	//
	// fetchOrders, fetchOpenOrders, fetchOrder, createOrder
	//
	//           {
	//                "order_id": "0x0101010503e693410000000069530a7d",
	//                "sub_account_id": "2147050003876484",
	//                "is_market": false,
	//                "time_in_force": "GOOD_TILL_TIME",
	//                "post_only": false,
	//                "reduce_only": false,
	//                "legs": [
	//                    {
	//                        "instrument": "BTC_USDT_Perp",
	//                        "size": "0.002",
	//                        "limit_price": "88123.0",
	//                        "is_buying_asset": true
	//                    }
	//                ],
	//                "signature": {
	//                    "signer": "0x0982ebb82523fd20d1347d59f5a989ed84caa4b5",
	//                    "r": "0x22b13e5bc7c8d6793db9d0adf6a51340437292baf83aa4f89a01a3c0c1fef4a8",
	//                    "s": "0x46ecd483126c388cc933022979a9636670f64af3773d04a84ecbeac423e69341",
	//                    "v": "28",
	//                    "expiration": "1767871961406000000",
	//                    "nonce": "588129369",
	//                    "chain_id": "0"
	//                },
	//                "metadata": {
	//                    "client_order_id": "588129369",
	//                    "create_time": "1765279966899943792",
	//                    "trigger": {
	//                        "trigger_type": "UNSPECIFIED",
	//                        "tpsl": {
	//                            "trigger_by": "UNSPECIFIED",
	//                            "trigger_price": "0.0",
	//                            "close_position": false
	//                        }
	//                    },
	//                    "broker": "UNSPECIFIED",
	//                    "is_position_transfer": false,
	//                    "allow_crossing": false
	//                },
	//                "state": {
	//                    "status": "OPEN",
	//                    "reject_reason": "UNSPECIFIED",
	//                    "book_size": [
	//                        "0.002"
	//                    ],
	//                    "traded_size": [
	//                        "0.0"
	//                    ],
	//                    "update_time": "1765279966899943792",
	//                    "avg_fill_price": [
	//                        "0.0"
	//                    ]
	//                },
	//                "builder": "0x00",
	//                "builder_fee": "0.0"
	//            }
	//
	// cancelOrder, cancelAllOrders
	//
	//    {
	//        "ack": true
	//    }
	//
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	if IsTrue(InOp(order, "ack")) {
		return this.SafeOrder(map[string]any{
			"info": order,
			"id":   nil,
		})
	}
	var isMarket any = this.SafeBool(order, "is_market")
	var orderType any = Ternary(IsTrue((IsEqual(isMarket, true))), "market", "limit")
	var isPostOnly any = this.SafeBool(order, "post_only")
	var isReduceOnly any = this.SafeBool(order, "reduce_only")
	var timeInForceRaw any = this.SafeString(order, "time_in_force")
	var timeInForce any = Ternary(IsTrue((IsEqual(isPostOnly, true))), "PO", this.ParseTimeInForce(timeInForceRaw))
	var size any = nil
	var side any = nil
	var price any = nil
	var filled any = nil
	var avgPrice any = nil
	var legs any = this.SafeList(order, "legs", []any{})
	var metadata any = this.SafeDict(order, "metadata", map[string]any{})
	var stateObj any = this.SafeDict(order, "state", map[string]any{})
	var filledAmounts any = this.SafeList(stateObj, "traded_size", []any{})
	var avgPrices any = this.SafeList(stateObj, "avg_fill_price", []any{})
	var primaryOrderIndex int = 0
	var firstLeg any = this.SafeDict(legs, primaryOrderIndex)
	if IsTrue(!IsEqual(firstLeg, nil)) {
		var marketId any = this.SafeString(firstLeg, "instrument")
		market = this.SafeMarket(marketId, market)
		size = this.SafeString(firstLeg, "size")
		var isBuyingAsset bool = (IsEqual(this.SafeBool(firstLeg, "is_buying_asset"), true))
		side = Ternary(IsTrue(isBuyingAsset), "buy", "sell")
		price = this.SafeString(firstLeg, "limit_price")
		filled = this.SafeString(filledAmounts, primaryOrderIndex)
		avgPrice = this.SafeString(avgPrices, primaryOrderIndex)
	}
	var timestamp any = this.SafeIntegerProduct(metadata, "create_time", 0.000001)
	// const triggerDetails = this.safeDict (metadata, 'trigger', {});
	var legsLength int = GetArrayLength(legs)
	return this.SafeOrder(map[string]any{
		"isMultiLeg":          (IsGreaterThan(legsLength, 1)),
		"id":                  this.SafeString(order, "order_id"),
		"clientOrderId":       this.SafeString(metadata, "client_order_id"),
		"timestamp":           timestamp,
		"datetime":            this.Iso8601(timestamp),
		"lastTradeTimeStamp":  nil,
		"lastUpdateTimestamp": this.SafeIntegerProduct(stateObj, "update_time", 0.000001),
		"status":              this.ParseOrderStatus(this.SafeString(stateObj, "status")),
		"symbol":              this.SafeString(market, "symbol"),
		"type":                orderType,
		"timeInForce":         timeInForce,
		"postOnly":            isPostOnly,
		"side":                side,
		"price":               price,
		"triggerPrice":        nil,
		"cost":                nil,
		"average":             avgPrice,
		"amount":              size,
		"filled":              filled,
		"remaining":           nil,
		"trades":              nil,
		"fees":                nil,
		"reduceOnly":          isReduceOnly,
		"info":                order,
	}, market)
}
func (this *Grvt) ParseTimeInForce(typeVar any) any {
	var types map[string]any = map[string]any{
		"GOOD_TILL_TIME":           "GTC",
		"IMMEDIATE_OR_CANCEL":      "IOC",
		"FILL_OR_KILL":             "FOK",
		"ALL_OR_NONE":              "ALL_OR_NONE",
		"RETAIL_PRICE_IMPROVEMENT": "RETAIL_PRICE_IMPROVEMENT",
	}
	return this.SafeStringUpper(types, typeVar, typeVar)
}
func (this *Grvt) TimeInForceToInt(timeInForce any) any {
	var timeInForces map[string]any = map[string]any{
		"GOOD_TILL_TIME":           1,
		"ALL_OR_NONE":              2,
		"IMMEDIATE_OR_CANCEL":      3,
		"FILL_OR_KILL":             4,
		"RETAIL_PRICE_IMPROVEMENT": 5,
	}
	return this.SafeInteger(timeInForces, timeInForce, 0)
}
func (this *Grvt) ParseOrderStatus(status any) any {
	var statuses map[string]any = map[string]any{
		"PENDING":   "pending",
		"OPEN":      "open",
		"FILLED":    "closed",
		"REJECTED":  "rejected",
		"CANCELLED": "canceled",
	}
	return this.SafeString(statuses, status, status)
}

